import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .u32 %r<20>;
    .reg .u64 %rd<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<5>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    // row = blockIdx.y * blockDim.y + threadIdx.y
    mov.u32 %r4, %ctaid.y;
    mov.u32 %r5, %ntid.y;
    mov.u32 %r6, %tid.y;
    mad.lo.u32 %r7, %r4, %r5, %r6;

    // col = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r8, %ctaid.x;
    mov.u32 %r9, %ntid.x;
    mov.u32 %r10, %tid.x;
    mad.lo.u32 %r11, %r8, %r9, %r10;

    setp.ge.u32 %p1, %r7, %r1;
    setp.ge.u32 %p2, %r11, %r2;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    // A row pointer = A_ptr + row*K*4
    cvt.u64.u32 %rd4, %r7;
    cvt.u64.u32 %rd5, %r3;
    mul.lo.u64 %rd6, %rd4, %rd5;
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;

    // B col pointer = B_ptr + col*4
    cvt.u64.u32 %rd9, %r11;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd2, %rd10;

    // N stride in bytes = N*4
    cvt.u64.u32 %rd12, %r2;
    shl.b64 %rd13, %rd12, 2;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r12, 0;

LOOP_START:
    setp.ge.u32 %p4, %r12, %r3;
    @%p4 bra LOOP_END;

    cvt.u64.u32 %rd14, %r12;
    shl.b64 %rd15, %rd14, 2;
    add.u64 %rd16, %rd8, %rd15;
    ld.global.f32 %f2, [%rd16];

    ld.global.f32 %f3, [%rd11];

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.u64 %rd11, %rd11, %rd13;
    add.u32 %r12, %r12, 1;
    bra LOOP_START;

LOOP_END:
    cvt.u64.u32 %rd17, %r7;
    mul.lo.u64 %rd18, %rd17, %rd12;
    add.u64 %rd18, %rd18, %rd9;
    shl.b64 %rd19, %rd18, 2;
    add.u64 %rd19, %rd3, %rd19;
    st.global.f32 [%rd19], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions of A and B must match"

        C = torch.empty((M, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid = (
            (N + block[0] - 1) // block[0],
            (M + block[1] - 1) // block[1],
            1,
        )

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

